const CACHE_TTL = 5 * 60 * 1000;
const orderCache = new Map();
const inFlightRequests = new Map();
export function normalizeList(value) {
    if (!value) {
        return [];
    }
    return Array.isArray(value) ? value : Object.values(value);
}
export function getProductRatings(rating) {
    if (!rating) {
        return [];
    }
    return [
        ...normalizeList(rating.product),
        ...normalizeList(rating.products),
    ];
}
export function extractFactors(source) {
    if (!source) {
        return [];
    }
    for (const key of ['factor_reviews', 'review_factors', 'factors']) {
        const value = source[key];
        if (Array.isArray(value) && value.length) {
            return value;
        }
    }
    return [];
}
export function findProductRating(productRatings, ratingId, productId, itemId) {
    return productRatings.find((productRating) => {
        if (ratingId && Number(productRating.id ?? productRating.feedback_id) === Number(ratingId)) {
            return true;
        }
        if (itemId && Number(productRating.order_item_id) === Number(itemId)) {
            return true;
        }
        if (productId && Number(productRating.product_id ?? productRating.product?.id) === Number(productId)) {
            return true;
        }
        return false;
    });
}
export function resolveReviewFactors(order, ratingId, productId, itemId) {
    const productRatings = getProductRatings(order?.rating);
    const productRating = findProductRating(productRatings, ratingId, productId, itemId);
    return extractFactors(productRating);
}
export async function fetchOrder(orderId) {
    if (orderId == null || orderId === '') {
        return null;
    }
    const cacheKey = String(orderId);
    const cached = orderCache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp <= CACHE_TTL) {
        return cached.data;
    }
    const pending = inFlightRequests.get(cacheKey);
    if (pending) {
        return pending;
    }
    const request = (async () => {
        try {
            const response = await salla.api.request(`orders/${orderId}`, '', 'get');
            const data = response?.data ?? response;
            orderCache.set(cacheKey, { data, timestamp: Date.now() });
            return data;
        }
        catch (error) {
            orderCache.delete(cacheKey);
            throw error;
        }
        finally {
            inFlightRequests.delete(cacheKey);
        }
    })();
    inFlightRequests.set(cacheKey, request);
    return request;
}
export function resetOrderCacheForTests() {
    orderCache.clear();
    inFlightRequests.clear();
}
